
const WORDS=[{"id": 0, "w": "捧", "p": "pěng", "t": "动词", "m": "nâng, bê, cầm bằng hai tay", "coll": "捧着书、捧起水杯", "s": "小女孩双手捧着一本书认真地读着上面的故事。"}, {"id": 1, "w": "天文", "p": "tiānwén", "t": "名词", "m": "thiên văn học", "coll": "天文知识、天文观测", "s": "这本书用通俗的语言介绍了一些基本的天文知识。"}, {"id": 2, "w": "儒家", "p": "rújiā", "t": "名词", "m": "Nho gia, trường phái Nho học", "coll": "儒家思想、儒家经典", "s": "这门课程通过具体材料介绍了儒家思想中的一些重要概念。"}, {"id": 3, "w": "传记", "p": "zhuànjì", "t": "名词", "m": "truyện ký, tiểu sử", "coll": "人物传记、阅读传记", "s": "阅读这位作家的传记让她进一步了解了作品背后的生活经历。"}, {"id": 4, "w": "散文", "p": "sǎnwén", "t": "名词", "m": "tản văn, văn xuôi", "coll": "一篇散文、散文集", "s": "这篇散文通过日常生活中的小事表达了作者对家乡的感情。"}, {"id": 5, "w": "历代", "p": "lìdài", "t": "名词", "m": "các triều đại, các đời (phong kiến)", "coll": "历代作品、历代学者", "s": "展览汇集了历代的相关作品帮助观众了解这门艺术的发展。"}, {"id": 6, "w": "着迷", "p": "zháomí", "t": "动词", "m": "say mê, mê mẩn", "coll": "令人着迷、对音乐着迷", "s": "窗外奇特的景象让孩子们十分着迷大家都停下来仔细观察。"}, {"id": 7, "w": "熏陶", "p": "xūntáo", "t": "动词", "m": "hun đúc, ảnh hưởng và bồi dưỡng qua môi trường văn hóa", "coll": "受到熏陶、文化熏陶", "s": "受到家人的熏陶，她从小就喜欢阅读也乐于记录生活。"}, {"id": 8, "w": "胸怀", "p": "xiōnghuái", "t": "名词", "m": "trái tim, tấm lòng, lòng", "coll": "宽广的胸怀、胸怀理想", "s": "面对不同的意见，他表现出宽广的胸怀愿意认真听取别人的想法。"}, {"id": 9, "w": "不堪", "p": "bùkān", "t": "动词", "m": "không chịu nổi, không chịu thấu", "coll": "疲惫不堪、不堪重负", "s": "连续忙碌了几天以后，大家都已经疲惫不堪决定先好好休息。"}, {"id": 10, "w": "炎热", "p": "yánrè", "t": "形容词", "m": "rất nóng, nóng cháy da", "coll": "天气炎热、炎热的夏天", "s": "天气炎热他把桌子搬到树下在那里继续读书。"}, {"id": 11, "w": "骚扰", "p": "sāorǎo", "t": "动词", "m": "quấy rối, làm phiền", "coll": "受到骚扰、骚扰他人", "s": "工作人员及时处理了游客反映的受到骚扰的问题。"}, {"id": 12, "w": "贫乏", "p": "pínfá", "t": "形容词", "m": "nghèo nàn, thiếu thốn", "coll": "内容贫乏、知识贫乏", "s": "这篇文章虽然篇幅很长内容却十分贫乏缺少具体的材料。"}, {"id": 13, "w": "艰难", "p": "jiānnán", "t": "形容词", "m": "gian nan, gian khổ", "coll": "生活艰难、艰难的选择", "s": "尽管生活艰难，他仍然坚持学习努力寻找新的机会。"}, {"id": 14, "w": "蜡烛", "p": "làzhú", "t": "名词", "m": "cây nến, đèn cầy", "coll": "点燃蜡烛、一支蜡烛", "s": "停电以后，她点燃一支蜡烛把它放在稳固的烛台上。"}, {"id": 15, "w": "蚂蚁", "p": "mǎyǐ", "t": "名词", "m": "(con) kiến", "coll": "一只蚂蚁、蚂蚁搬家", "s": "孩子蹲在树旁观察一只蚂蚁怎样搬运食物。"}, {"id": 16, "w": "颈椎", "p": "jǐngzhuī", "t": "名词", "m": "(các) đốt sống cổ", "coll": "颈椎结构、颈椎模型", "s": "老师借助模型向学生介绍了颈椎的基本结构。"}, {"id": 17, "w": "揉", "p": "róu", "t": "动词", "m": "dụi, vò, xoa bóp", "coll": "揉眼睛、揉面团", "s": "面点师把准备好的面团放在案板上反复揉匀。"}, {"id": 18, "w": "挪", "p": "nuó", "t": "动词", "m": "xê dịch, dịch chuyển", "coll": "挪动桌子、往旁边挪", "s": "为了腾出通道，他把椅子往旁边挪了一点。"}, {"id": 19, "w": "屁股", "p": "pìgu", "t": "名词", "m": "mông", "coll": "坐在屁股下面、屁股着地", "s": "小男孩在草地上滑了一下屁股着地，随后自己站了起来。"}, {"id": 20, "w": "知觉", "p": "zhījué", "t": "名词", "m": "cảm giác", "coll": "失去知觉、恢复知觉", "s": "小说中的人物醒来以后才发现自己的手指已经恢复知觉。"}, {"id": 21, "w": "挨", "p": "ái", "t": "动词", "m": "chịu đựng, bị", "coll": "挨批评、挨打", "s": "因为没有按时完成任务他挨了批评，随后认真改正了问题。"}, {"id": 22, "w": "美满", "p": "měimǎn", "t": "形容词", "m": "mỹ mãn, đầy đủ", "coll": "生活美满、美满的家庭", "s": "她虽然工作繁忙却很珍惜眼前美满的家庭生活。"}, {"id": 23, "w": "天堂", "p": "tiāntáng", "t": "名词", "m": "thiên đường", "coll": "仿佛天堂、心中的天堂", "s": "对于热爱阅读的人来说，这座安静的图书馆仿佛就是心中的天堂。"}, {"id": 24, "w": "熄灭", "p": "xīmiè", "t": "动词", "m": "tắt, dập tắt", "coll": "蜡烛熄灭、熄灭灯火", "s": "风从窗外吹来桌上的蜡烛突然熄灭屋子里顿时暗了下来。"}, {"id": 25, "w": "泄气", "p": "xièqì", "t": "动词", "m": "nản lòng, nhụt chí", "coll": "不要泄气、感到泄气", "s": "虽然这次没有成功，他，却没有泄气，而是重新总结经验。"}, {"id": 26, "w": "眯", "p": "mī", "t": "动词", "m": "nheo (mắt), hé nhìn", "coll": "眯着眼睛、眯起眼睛", "s": "阳光照过来他眯起眼睛望向远处的山峰。"}, {"id": 27, "w": "绝望", "p": "juéwàng", "t": "动词／形容词", "m": "tuyệt vọng, mất hy vọng", "coll": "感到绝望、陷入绝望", "s": "一连几次受挫让他一度感到绝望后来才慢慢找回信心。"}, {"id": 28, "w": "凝固", "p": "nínggù", "t": "动词", "m": "cứng lại, đông đặc", "coll": "逐渐凝固、凝固成形", "s": "倒进模具的材料慢慢凝固最后形成了完整的形状。"}, {"id": 29, "w": "蔓延", "p": "mànyán", "t": "动词", "m": "lan rộng, lan ra", "coll": "迅速蔓延、向四周蔓延", "s": "雾气沿着山谷慢慢蔓延逐渐遮住了远处的树木。"}, {"id": 30, "w": "克制", "p": "kèzhì", "t": "动词", "m": "kiềm chế, nén", "coll": "克制情绪、保持克制", "s": "听到不同意见，他努力克制自己的情绪继续平静地讨论问题。"}, {"id": 31, "w": "默默", "p": "mòmò", "t": "副词", "m": "thầm, lặng lẽ", "coll": "默默付出、默默支持", "s": "这些年她一直默默支持朋友从不主动提起自己的帮助。"}, {"id": 32, "w": "背诵", "p": "bèisòng", "t": "动词", "m": "đọc thuộc lòng", "coll": "背诵课文、熟练背诵", "s": "理解文章的意思以后，学生再尝试背诵课文记住其中重要的表达。"}, {"id": 33, "w": "编织", "p": "biānzhī", "t": "动词", "m": "đan, kết lại", "coll": "编织篮子、编织故事", "s": "老人坐在院子里用细细的竹条编织一个小篮子。"}, {"id": 34, "w": "强制", "p": "qiángzhì", "t": "动词", "m": "cưỡng chế, ép buộc", "coll": "强制执行、强制要求", "s": "这项规定并不强制所有人使用同一种工具，而是允许大家根据需要选择。"}, {"id": 35, "w": "田野", "p": "tiányě", "t": "名词", "m": "đồng ruộng", "coll": "广阔的田野、走向田野", "s": "夕阳下广阔的田野呈现出柔和的金色。"}, {"id": 36, "w": "情形", "p": "qíngxing", "t": "名词", "m": "tình hình, hoàn cảnh, tình huống", "coll": "具体情形、了解情形", "s": "作出判断以前，我们应该先了解当时的具体情形。"}, {"id": 37, "w": "耀眼", "p": "yàoyǎn", "t": "形容词", "m": "chói mắt, lóa mắt", "coll": "阳光耀眼、耀眼的灯光", "s": "广场上的灯光十分耀眼把周围的建筑也照得清清楚楚。"}, {"id": 38, "w": "光芒", "p": "guāngmáng", "t": "名词", "m": "hào quang, ánh sáng", "coll": "发出光芒、柔和的光芒", "s": "小小的灯笼发出柔和的光芒照亮了孩子手中的书页。"}, {"id": 39, "w": "捞", "p": "lāo", "t": "动词", "m": "moi, mò, vớt", "coll": "捞起来、捞鱼", "s": "他用小网把落进水里的树叶捞了起来。"}, {"id": 40, "w": "摊", "p": "tān", "t": "动词", "m": "trải ra, mở ra", "coll": "摊开地图、摊在桌上", "s": "准备出发之前，大家把地图摊在桌上商量第二天的路线。"}, {"id": 41, "w": "哇", "p": "wā", "t": "叹词", "m": "oa, ôi, chao (cảm thán)", "coll": "哇，真美、哇，太棒了", "s": "哇，远处山谷里的灯光竟然像星星一样明亮。"}, {"id": 42, "w": "毫米", "p": "háomǐ", "t": "量词", "m": "mi-li-mét", "coll": "一毫米、几毫米", "s": "观察记录上清楚地写着这块材料的厚度只有两毫米。"}, {"id": 43, "w": "迸发", "p": "bèngfā", "t": "动词", "m": "tóe ra, bùng ra, nảy ra", "coll": "迸发活力、迸发灵感", "s": "与同伴交流以后，她迸发出新的灵感很快画出了设计草图。"}, {"id": 44, "w": "兜", "p": "dōu", "t": "名词", "m": "túi", "coll": "衣兜、裤兜", "s": "出门的时候，他把一张写着地址的纸条放进了衣兜。"}, {"id": 45, "w": "灯笼", "p": "dēnglong", "t": "名词", "m": "đèn lồng", "coll": "挂灯笼、一盏灯笼", "s": "节日前夕大家在院子里挂起灯笼准备迎接远方的客人。"}, {"id": 46, "w": "啦", "p": "la", "t": "助词", "m": "đấy, nhé, kìa", "coll": "出发啦、完成啦", "s": "准备好啦，大家可以带上行李一起出发了。"}, {"id": 47, "w": "天赋", "p": "tiānfù", "t": "名词", "m": "tài năng, năng khiếu", "coll": "音乐天赋、发挥天赋", "s": "她虽然有音乐天赋，却仍然每天坚持认真练习。"}, {"id": 48, "w": "贫困", "p": "pínkùn", "t": "形容词", "m": "nghèo khó, nghèo túng", "coll": "生活贫困、摆脱贫困", "s": "尽管家境贫困，他依然珍惜学习机会努力改变自己的生活。"}, {"id": 49, "w": "财富", "p": "cáifù", "t": "名词", "m": "của cải", "coll": "宝贵财富、精神财富", "s": "那些记录普通人生活的照片如今已经成为一笔宝贵的文化财富。"}, {"id": 50, "w": "源泉", "p": "yuánquán", "t": "名词", "m": "nguồn, cội nguồn", "coll": "灵感源泉、力量的源泉", "s": "对她来说，家乡的生活始终是创作灵感的重要源泉。"}];
const CHUNKS=[["小女孩", "双手捧着一本书", "认真地", "读着上面的故事。"], ["这本书", "用通俗的语言", "介绍了", "一些基本的天文知识。"], ["这门课程", "通过具体材料", "介绍了", "儒家思想中的一些重要概念。"], ["阅读这位作家的传记", "让她", "进一步了解了", "作品背后的生活经历。"], ["这篇散文", "通过日常生活中的小事", "表达了", "作者对家乡的感情。"], ["展览", "汇集了历代的相关作品", "帮助观众", "了解这门艺术的发展。"], ["窗外奇特的景象", "让孩子们十分着迷", "大家", "都停下来仔细观察。"], ["受到家人的熏陶，", "她", "从小就喜欢阅读", "也乐于记录生活。"], ["面对不同的意见，", "他", "表现出宽广的胸怀", "愿意认真听取别人的想法。"], ["连续忙碌了几天以后，", "大家", "都已经疲惫不堪", "决定先好好休息。"], ["天气炎热", "他", "把桌子搬到树下", "在那里继续读书。"], ["工作人员", "及时处理了", "游客反映的", "受到骚扰的问题。"], ["这篇文章", "虽然篇幅很长", "内容却十分贫乏", "缺少具体的材料。"], ["尽管生活艰难，", "他", "仍然坚持学习", "努力寻找新的机会。"], ["停电以后，", "她", "点燃一支蜡烛", "把它放在稳固的烛台上。"], ["孩子", "蹲在树旁", "观察一只蚂蚁", "怎样搬运食物。"], ["老师", "借助模型", "向学生", "介绍了颈椎的基本结构。"], ["面点师", "把准备好的面团", "放在案板上", "反复揉匀。"], ["为了腾出通道，", "他", "把椅子", "往旁边挪了一点。"], ["小男孩", "在草地上滑了一下", "屁股着地，", "随后自己站了起来。"], ["小说中的人物", "醒来以后", "才发现", "自己的手指已经恢复知觉。"], ["因为没有按时完成任务", "他", "挨了批评，", "随后认真改正了问题。"], ["她", "虽然工作繁忙", "却很珍惜", "眼前美满的家庭生活。"], ["对于热爱阅读的人来说，", "这座安静的图书馆", "仿佛", "就是心中的天堂。"], ["风从窗外吹来", "桌上的蜡烛", "突然熄灭", "屋子里顿时暗了下来。"], ["虽然这次没有成功，", "他，", "却没有泄气，", "而是重新总结经验。"], ["阳光照过来", "他", "眯起眼睛", "望向远处的山峰。"], ["一连几次受挫", "让他", "一度感到绝望", "后来才慢慢找回信心。"], ["倒进模具的材料", "慢慢凝固", "最后", "形成了完整的形状。"], ["雾气", "沿着山谷", "慢慢蔓延", "逐渐遮住了远处的树木。"], ["听到不同意见，", "他", "努力克制自己的情绪", "继续平静地讨论问题。"], ["这些年", "她", "一直默默支持朋友", "从不主动提起自己的帮助。"], ["理解文章的意思以后，", "学生", "再尝试背诵课文", "记住其中重要的表达。"], ["老人", "坐在院子里", "用细细的竹条", "编织一个小篮子。"], ["这项规定", "并不强制所有人使用同一种工具，", "而是", "允许大家根据需要选择。"], ["夕阳下", "广阔的田野", "呈现出", "柔和的金色。"], ["作出判断以前，", "我们", "应该先了解", "当时的具体情形。"], ["广场上的灯光", "十分耀眼", "把周围的建筑", "也照得清清楚楚。"], ["小小的灯笼", "发出柔和的光芒", "照亮了", "孩子手中的书页。"], ["他", "用小网", "把落进水里的树叶", "捞了起来。"], ["准备出发之前，", "大家", "把地图摊在桌上", "商量第二天的路线。"], ["哇，", "远处山谷里的灯光", "竟然", "像星星一样明亮。"], ["观察记录上", "清楚地写着", "这块材料的厚度", "只有两毫米。"], ["与同伴交流以后，", "她", "迸发出新的灵感", "很快画出了设计草图。"], ["出门的时候，", "他", "把一张写着地址的纸条", "放进了衣兜。"], ["节日前夕", "大家", "在院子里挂起灯笼", "准备迎接远方的客人。"], ["准备好啦，", "大家", "可以带上行李", "一起出发了。"], ["她", "虽然有音乐天赋，", "却仍然", "每天坚持认真练习。"], ["尽管家境贫困，", "他", "依然珍惜学习机会", "努力改变自己的生活。"], ["那些记录普通人生活的照片", "如今", "已经成为", "一笔宝贵的文化财富。"], ["对她来说，", "家乡的生活", "始终是", "创作灵感的重要源泉。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai26-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/51 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),51)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共51个词语，点击 ↗ 学习该词语',totalLearned()+'/51 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===50;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<50){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:10};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课51个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课51个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [0, 17, 18], "5": [0, 17, 18], "8": [0, 17, 18], "11": [1, 3, 14], "14": [0, 17, 18], "17": [1, 3, 14], "20": [0, 17, 18], "23": [0, 17, 18], "26": [1, 3, 14], "29": [1, 3, 14], "32": [1, 3, 14], "35": [0, 17, 18], "38": [0, 17, 18], "41": [1, 3, 14], "44": [0, 17, 18], "47": [1, 3, 14], "50": [0, 17, 18]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的51个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第26课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第26课学习进度','第26课 · 51个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 51</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第26课';$('ntc-bookmark').textContent=student?total+'/51 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第26课学习进度</div><div style="padding:0 10px">'+total+'/51 个已学词语'+meter(total,51)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"捧":"data:audio/mpeg;base64,","小女孩双手捧着一本书认真地读着上面的故事。":"data:audio/mpeg;base64,","天文":"data:audio/mpeg;base64,","这本书用通俗的语言介绍了一些基本的天文知识。":"data:audio/mpeg;base64,","儒家":"data:audio/mpeg;base64,","这门课程通过具体材料介绍了儒家思想中的一些重要概念。":"data:audio/mpeg;base64,","传记":"data:audio/mpeg;base64,","阅读这位作家的传记让她进一步了解了作品背后的生活经历。":"data:audio/mpeg;base64,","散文":"data:audio/mpeg;base64,","这篇散文通过日常生活中的小事表达了作者对家乡的感情。":"data:audio/mpeg;base64,","历代":"data:audio/mpeg;base64,","展览汇集了历代的相关作品帮助观众了解这门艺术的发展。":"data:audio/mpeg;base64,","着迷":"data:audio/mpeg;base64,","窗外奇特的景象让孩子们十分着迷大家都停下来仔细观察。":"data:audio/mpeg;base64,","熏陶":"data:audio/mpeg;base64,","受到家人的熏陶，她从小就喜欢阅读也乐于记录生活。":"data:audio/mpeg;base64,","胸怀":"data:audio/mpeg;base64,","面对不同的意见，他表现出宽广的胸怀愿意认真听取别人的想法。":"data:audio/mpeg;base64,","不堪":"data:audio/mpeg;base64,","连续忙碌了几天以后，大家都已经疲惫不堪决定先好好休息。":"data:audio/mpeg;base64,","炎热":"data:audio/mpeg;base64,","天气炎热他把桌子搬到树下在那里继续读书。":"data:audio/mpeg;base64,","骚扰":"data:audio/mpeg;base64,","工作人员及时处理了游客反映的受到骚扰的问题。":"data:audio/mpeg;base64,","贫乏":"data:audio/mpeg;base64,","这篇文章虽然篇幅很长内容却十分贫乏缺少具体的材料。":"data:audio/mpeg;base64,","艰难":"data:audio/mpeg;base64,","尽管生活艰难，他仍然坚持学习努力寻找新的机会。":"data:audio/mpeg;base64,","蜡烛":"data:audio/mpeg;base64,","停电以后，她点燃一支蜡烛把它放在稳固的烛台上。":"data:audio/mpeg;base64,","蚂蚁":"data:audio/mpeg;base64,","孩子蹲在树旁观察一只蚂蚁怎样搬运食物。":"data:audio/mpeg;base64,","颈椎":"data:audio/mpeg;base64,","老师借助模型向学生介绍了颈椎的基本结构。":"data:audio/mpeg;base64,","揉":"data:audio/mpeg;base64,","面点师把准备好的面团放在案板上反复揉匀。":"data:audio/mpeg;base64,","挪":"data:audio/mpeg;base64,","为了腾出通道，他把椅子往旁边挪了一点。":"data:audio/mpeg;base64,","屁股":"data:audio/mpeg;base64,","小男孩在草地上滑了一下屁股着地，随后自己站了起来。":"data:audio/mpeg;base64,","知觉":"data:audio/mpeg;base64,","小说中的人物醒来以后才发现自己的手指已经恢复知觉。":"data:audio/mpeg;base64,","挨":"data:audio/mpeg;base64,","因为没有按时完成任务他挨了批评，随后认真改正了问题。":"data:audio/mpeg;base64,","美满":"data:audio/mpeg;base64,","她虽然工作繁忙却很珍惜眼前美满的家庭生活。":"data:audio/mpeg;base64,","天堂":"data:audio/mpeg;base64,","对于热爱阅读的人来说，这座安静的图书馆仿佛就是心中的天堂。":"data:audio/mpeg;base64,","熄灭":"data:audio/mpeg;base64,","风从窗外吹来桌上的蜡烛突然熄灭屋子里顿时暗了下来。":"data:audio/mpeg;base64,","泄气":"data:audio/mpeg;base64,","虽然这次没有成功，他，却没有泄气，而是重新总结经验。":"data:audio/mpeg;base64,","眯":"data:audio/mpeg;base64,","阳光照过来他眯起眼睛望向远处的山峰。":"data:audio/mpeg;base64,","绝望":"data:audio/mpeg;base64,","一连几次受挫让他一度感到绝望后来才慢慢找回信心。":"data:audio/mpeg;base64,","凝固":"data:audio/mpeg;base64,","倒进模具的材料慢慢凝固最后形成了完整的形状。":"data:audio/mpeg;base64,","蔓延":"data:audio/mpeg;base64,","雾气沿着山谷慢慢蔓延逐渐遮住了远处的树木。":"data:audio/mpeg;base64,","克制":"data:audio/mpeg;base64,","听到不同意见，他努力克制自己的情绪继续平静地讨论问题。":"data:audio/mpeg;base64,","默默":"data:audio/mpeg;base64,","这些年她一直默默支持朋友从不主动提起自己的帮助。":"data:audio/mpeg;base64,","背诵":"data:audio/mpeg;base64,","理解文章的意思以后，学生再尝试背诵课文记住其中重要的表达。":"data:audio/mpeg;base64,","编织":"data:audio/mpeg;base64,","老人坐在院子里用细细的竹条编织一个小篮子。":"data:audio/mpeg;base64,","强制":"data:audio/mpeg;base64,","这项规定并不强制所有人使用同一种工具，而是允许大家根据需要选择。":"data:audio/mpeg;base64,","田野":"data:audio/mpeg;base64,","夕阳下广阔的田野呈现出柔和的金色。":"data:audio/mpeg;base64,","情形":"data:audio/mpeg;base64,","作出判断以前，我们应该先了解当时的具体情形。":"data:audio/mpeg;base64,","耀眼":"data:audio/mpeg;base64,","广场上的灯光十分耀眼把周围的建筑也照得清清楚楚。":"data:audio/mpeg;base64,","光芒":"data:audio/mpeg;base64,","小小的灯笼发出柔和的光芒照亮了孩子手中的书页。":"data:audio/mpeg;base64,","捞":"data:audio/mpeg;base64,","他用小网把落进水里的树叶捞了起来。":"data:audio/mpeg;base64,","摊":"data:audio/mpeg;base64,","准备出发之前，大家把地图摊在桌上商量第二天的路线。":"data:audio/mpeg;base64,","哇":"data:audio/mpeg;base64,","哇，远处山谷里的灯光竟然像星星一样明亮。":"data:audio/mpeg;base64,","毫米":"data:audio/mpeg;base64,","观察记录上清楚地写着这块材料的厚度只有两毫米。":"data:audio/mpeg;base64,","迸发":"data:audio/mpeg;base64,","与同伴交流以后，她迸发出新的灵感很快画出了设计草图。":"data:audio/mpeg;base64,","兜":"data:audio/mpeg;base64,","出门的时候，他把一张写着地址的纸条放进了衣兜。":"data:audio/mpeg;base64,","灯笼":"data:audio/mpeg;base64,","节日前夕大家在院子里挂起灯笼准备迎接远方的客人。":"data:audio/mpeg;base64,","啦":"data:audio/mpeg;base64,","准备好啦，大家可以带上行李一起出发了。":"data:audio/mpeg;base64,","天赋":"data:audio/mpeg;base64,","她虽然有音乐天赋，却仍然每天坚持认真练习。":"data:audio/mpeg;base64,","贫困":"data:audio/mpeg;base64,","尽管家境贫困，他依然珍惜学习机会努力改变自己的生活。":"data:audio/mpeg;base64,","财富":"data:audio/mpeg;base64,","那些记录普通人生活的照片如今已经成为一笔宝贵的文化财富。":"data:audio/mpeg;base64,","源泉":"data:audio/mpeg;base64,","对她来说，家乡的生活始终是创作灵感的重要源泉。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai26-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai26_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai26-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=51)||!p.memory)throw Error();if(!confirm('恢复第26课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<51;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<51&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第26课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

